import ast

def score(program: str) -> float:
    try:
        tree = ast.parse(program)
    except Exception:
        return 0.5
    nodes = list(ast.walk(tree))
    kinds = set(type(n).__name__ for n in nodes)
    value = len(nodes) / 250 + len(kinds) / 60
    return float(min(value, 1.0))

